"""Write proposed declarative total-stress record; no shared mutation."""
from pathlib import Path
import json,sys
P=Path(__file__).parent
m={'schema_version':'0.3','id':'tresca-associated-perfect-bk2022v1-be-research','name':'Tresca — associated perfect plasticity (BK2022v1, project BE)','family':'elastoplasticity','status':'draft','description':'Named author-preprint associated isotropic elastic-perfect plastic closure plus separately project-derived backward-Euler metric projection. Total Cauchy stress; no pore-pressure law. Compression-positive infinitesimal strain and stress map to negatives of source variables; fixed spatial zero-spin restriction, orthonormal Mandel order xx,yy,zz,sqrt2xy,sqrt2yz,sqrt2xz. Persistent sigma and plastic strain ep, both explicitly initialized. Numerical example only: lambda=30MPa,mu=20MPa,k=50kPa,sigma=100kPa I,ep=0; no experimental calibration or soil-preparation claim. Compatible initial elastic/total strain is I/1300, while plotted strain increments start from that preparation. No public browser admission: synthetic confinement-difference must not be called pore pressure for this total-stress law. No finite-spin, zero-strength, cap, smoothing, hardening or MC-zero-angle specialization.','sources':[{'url':'https://arxiv.org/abs/2207.12719v1','locator':'Boulmezaoud and Khouider,2022v1; exactPDF SHA256 db7fb284eb9bb622883d5daff6361db37cab912b890b8a24ed99a2428abc7805,258014bytes25pages. pp2–3Eqs1–8 additive/Hooke/normality, p7Eqs34–37 positiveconstantLameelasticity,pp15–16Eqs77–81 Tresca k>0,pp18–21Eqs89–108 repeatednormalcone.','role':'primary complete continuum associated perfect-plastic closure; not printed finite BE algorithm'}],'parameters':{},'state':[],'derived':[],'equations':{},'domain':[],'initial_checks':[]}
for n,v,label in [('p_ref',100000.,'Numerical reference stress (not soil parameter)'),('lame_lambda',30000000.,'Constant positive first Lame modulus'),('mu',20000000.,'Constant positive shear modulus'),('k',50000.,'Constant positive maximum-shear yield strength; uniaxial Y=2k')]:m['parameters'][n]={'default':v,'min':0.,'max':sys.float_info.max,'unit':'Pa','label':label}
for n,unit,initial,scale,quantity in [('sigma','Pa',[100000.,100000.,100000.,0.,0.,0.],'p_ref','cauchy_stress'),('ep','1',[0.]*6,'1','infinitesimal_plastic_strain')]:m['state'].append({'name':n,'shape':'sym','unit':unit,'initial':initial,'scale':scale,'semantics':{'role':'persistent','quantity':quantity,'transformation':'symmetric_spatial_tensor'}})
der=[('width','2*k'),('trial','sigma_n+2*mu*de+lame_lambda*trace(de)*I'),('trace_trial','trace(trial)'),('vmax','principal_max_value(trial)'),('vmid','principal_mid_value(trial)'),('vmin','principal_min_value(trial)'),('branch','select(vmax-vmin<=width,0,select(3*vmid>trace_trial+width,1,select(3*vmid<trace_trial-width,2,3)))'),('returned','select(branch<0.5,trial,select(branch<1.5,((trace_trial+width)/3)*I-width*projector_min(trial),select(branch<2.5,((trace_trial-width)/3)*I+width*projector_max(trial),trial-((principal_max(trial)-principal_min(trial)-width)/2)*(projector_max(trial)-projector_min(trial)))))')]
m['derived']=[{'name':n,'expr':e}for n,e in der]
m['equations']={'sigma':'sigma-returned','ep':'ep-ep_n-(trial-sigma)/(2*mu)+(lame_lambda/(3*lame_lambda+2*mu))*trace(trial-sigma)/(2*mu)*I'}
m['domain']=['p_ref>0*p_ref','lame_lambda>0*p_ref','mu>0*p_ref','k>0*p_ref']
m['initial_checks']=['principal_max_value(sigma)-principal_min_value(sigma)<=width']
m['formulation']={'time_dependence':'strain_path','equation_form':'incremental_residual','kinematics':'small_strain_3d','frame':'fixed_spatial','objective_rate':'none','tensor_representation':'mandel','stress_sign':'compression_positive','strain_sign':'compression_positive','inputs':{'equation':{'de':{'quantity':'strain_increment','measure':'infinitesimal_strain','shape':'sym','unit':'1','configuration':'current','sampling':'increment','constraint':'finite'}},'advance':{}},'stress':{'source':'state','name':'sigma','measure':'cauchy','scope':'total'}}
m['initialization']={'method':'explicit_state','default_policy':'examples_only','required_state':['sigma','ep'],'validation':'domain_and_initial_checks'}
(P/'model.json').write_text(json.dumps(m,indent=2,ensure_ascii=False)+'\n')
if __name__=='__main__':print(m['id'])
